#!/usr/bin/env python3
"""Render editorial comparisons; upstream claims are dated and linked beside the text."""
import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
record = json.loads((ROOT / 'data/conformance.json').read_text())
source = f"https://github.com/sunfall-labs/kiln/blob/{record['source_commit']}/"
reviewed = 'October 12, 2026'

pages = [
    ('kiln-vs-perry.html', 'kiln vs Perry', 'TypeScript to native: checking, packages, concurrency and UI.'),
    ('kiln-vs-static-hermes.html', 'kiln vs Static Hermes', 'Native JavaScript compilation, TypeScript workflows and host APIs.'),
    ('kiln-vs-porffor.html', 'kiln vs Porffor', 'Ahead-of-time compilation, npm projects and native HTTP servers.'),
]

def table(peer, rows):
    markup = '<p class="small-note comparison-hint">Scroll sideways to view both runtime columns.</p><div class="table-scroll" tabindex="0" role="region" aria-label="Feature comparison"><table class="comparison-table"><thead><tr><th scope="col">Consideration</th><th scope="col">kiln v0.1.0</th><th scope="col">' + html.escape(peer) + '</th></tr></thead><tbody>'
    for label, kiln, other in rows:
        markup += f'<tr><th scope="row">{html.escape(label)}</th><td>{kiln}</td><td>{other}</td></tr>'
    return markup + '</tbody></table></div>'

def cards():
    return '<div class="reference-links">' + ''.join(f'<a href="{path}"><strong>{title}</strong><span>{description} →</span></a>' for path,title,description in pages) + '</div>'

def document(path, title, description, body):
    ROOT.joinpath('compare',path).write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="{html.escape(description,quote=True)}"><title>{title} — kiln</title><link rel="icon" href="../mark.svg"><link rel="stylesheet" href="../style.css"></head><body><a class="skip" href="#main">Skip to content</a><div class="page"><header><a class="brand" href="../"><img src="../mark.svg" width="30" height="34" alt=""><span>kiln.</span></a><nav aria-label="Comparison navigation"><a href="./">Compare</a><a href="../reference/">Reference</a><a href="../#start">Install</a></nav></header><main id="main" class="reference"><div class="reference-heading"><span class="eyebrow">TYPESCRIPT / NATIVE RUNTIME COMPARISONS</span><h1>{title}</h1><p>{description}</p><p class="small-note">kiln v0.1.0 · upstream documentation reviewed {reviewed}</p></div>{body}</main><footer><a href="../">← kiln home</a><a href="./">All comparisons</a><a href="../reference/conformance.html">Inspect kiln’s evidence</a></footer></div></body></html>\n''')

index = '''<section><h2>Choose around the program you want to ship.</h2><p>Native TypeScript and JavaScript tools differ in more than their compilation backend. Source diagnostics, host APIs, module loading, ownership and target platforms determine how much of your existing application can move with you.</p><p>kiln combines an immediate interpreter with native builds, source TypeScript checking, Node-style package resolution and typed concurrency APIs. These pages compare that workflow with the documented approaches of other native compilers.</p>''' + cards() + '''<h2>What the comparisons establish.</h2><p>Each page cites upstream documentation and links to kiln’s pinned release evidence. They compare architecture and developer workflows. There are no matched performance results for these three pairings on this site. Published results from different machines, programs or execution modes do not establish a speed ranking.</p><p>For measured HTTP results against Node, Bun and Deno, see <a href="../#measured">the runtime measurements</a>. For package coverage, inspect <a href="../reference/npm-compatibility.html">every pinned npm smoke test</a>.</p></section>'''
document('index.html','Compare native TypeScript and JavaScript runtimes','kiln comparisons with Perry, Static Hermes and Porffor: TypeScript checking, npm compatibility, native compilation, concurrency and platform support.',index)

perry_table = table('Perry (documented)', [
    ('Native compilation', 'Generated C compiled with a system C compiler.', 'SWC parsing and LLVM machine-code generation.'),
    ('Development loop', '<code>kiln run</code> interprets; <code>kiln build</code> emits a binary.', '<code>perry run</code> compiles and launches; <code>perry dev</code> rebuilds on edits.'),
    ('Source checking', '<code>kiln check</code>; embedded checker and pinned TS7 libraries.', '<code>--type-check</code> invokes tsgo. <code>perry check</code> scans Perry compatibility.'),
    ('Concurrency', 'Proven parallel callbacks, typed actors and shared immutable graphs.', 'Parallel collection functions and background <code>spawn</code> threads.'),
    ('Native UI', 'AppKit provider on Apple Silicon macOS; Linux archive omits GUI.', 'Documents desktop, mobile and web UI targets.'),
])
perry = '''<section><h2>Two routes from TypeScript to an executable.</h2><p>kiln and Perry both let you ship a native binary from TypeScript. Perry uses SWC and LLVM and documents a broad platform UI offering. kiln focuses its v0.1.0 workflow on checking source, running it immediately, then compiling the program for macOS Apple Silicon or Linux x86_64. <a href="https://github.com/PerryTS/perry">Perry’s compiler and platform overview</a>.</p>''' + perry_table + '''<p class="small-note">Perry entries summarize its <a href="https://github.com/PerryTS/perry">project overview</a>, <a href="https://docs.perryts.com/cli/commands.html">CLI reference</a> and <a href="https://docs.perryts.com/threading/overview.html">threading guide</a>; they are documentation claims, not independently verified executions here.</p><h2>Type checking and compiler compatibility are different checks.</h2><p>Perry’s CLI separates compatibility scanning with <code>perry check</code> from TypeScript checking through <code>--type-check</code> and tsgo. <a href="https://docs.perryts.com/cli/commands.html">Perry command semantics</a>.</p><p>kiln’s embedded <code>kiln check</code> reports source diagnostics with TypeScript 7.0.2 declaration inputs. The release record has 11,980 exact reference-output matches out of 13,101 cases, plus 1,710 matches out of 2,226 differential cases. This makes the remaining diagnostic differences inspectable; it does not establish complete TS7 equivalence. <a href="../reference/type-checking.html">Checker commands and compatibility evidence</a>.</p><h2>Compare how values cross cores.</h2><p>Perry documents <code>parallelMap</code>, <code>parallelFilter</code> and <code>spawn</code>, with copied object values and restrictions on mutable captures. <a href="https://docs.perryts.com/threading/overview.html">Perry’s threading and transfer model</a>.</p><p>kiln’s collection methods use compiler effect proofs and sequential fallbacks. For stateful components, typed actors own separate realms and bounded mailboxes. Shared immutable snapshots let subsequent native sends retain a graph instead of cloning its fields. These APIs offer different ways to organize work; neither API shape alone predicts throughput. <a href="../reference/concurrency.html">Typed concurrency and ownership examples</a>.</p><h2>Which should you evaluate first?</h2><p>If your requirement is a wider native UI target set, compare Perry’s platform guides with kiln’s narrower released GUI provider. If you want one interpreter-to-native workflow with visible source-checker evidence, Node-oriented package tests and typed actor ownership, start with kiln’s runnable reference examples.</p><p>Both need validation against your actual dependencies. kiln records 361/361 passing pinned npm smoke tests in native-dev mode, not complete upstream package suites. <a href="../reference/npm-compatibility.html">Package names, versions and test scope</a>. Perry also documents Node and npm support; this page does not compare their percentages because the corpora differ. <a href="https://github.com/PerryTS/perry">Perry’s compatibility overview</a>.</p><h2>Try kiln’s workflow.</h2><pre><code>kiln check app.ts\nkiln run app.ts\nkiln build app.ts\n./app</code></pre><p><a href="../#start">Install kiln</a> or inspect <a href="../reference/builtins.html">the typed built-in modules</a>. No matched kiln-versus-Perry timing or binary-size run is published here.</p></section>'''
document('kiln-vs-perry.html','kiln vs Perry: TypeScript to Native Compared','Compare kiln and Perry for TypeScript checking, native binaries, npm projects, concurrency and native UI. Practical differences with linked source evidence.',perry)

hermes_table = table('Static Hermes (documented)', [
    ('Compilation approach', 'TypeScript/JavaScript lowered to generated C and a native executable.', 'Optional JavaScript AOT compilation; Clang/LLVM native and Wasm targets.'),
    ('Types and diagnostics', 'Source checker with pinned TypeScript 7.0.2 libraries and diagnostic baselines.', 'Optional sound typing is part of the Static Hermes design.'),
    ('Application surface', 'Node adapter, package resolution, HTTP and subprocess APIs.', 'JavaScript engine and runtime; assess the embedding host for application APIs.'),
    ('Published pairing results', 'No matched Static Hermes native-AOT results on this site.', 'The existing kiln harness lane executes Hermes bytecode, not native AOT.'),
])
hermes = '''<section><h2>A native application workflow and a JavaScript engine project.</h2><p>Static Hermes explores optional sound typing and ahead-of-time JavaScript compilation in the Hermes <code>static_h</code> branch. Its published design describes Clang/LLVM generation for native code and WebAssembly, retaining an interpreter for dynamic code such as eval. <a href="https://github.com/facebook/hermes/blob/static_h/doc/blog/2024-12-23-compiling-javascript-to-wasm.md">Static Hermes’s native compilation explanation</a>.</p><p>kiln packages an application workflow around TypeScript: source checking, immediate interpretation, native builds, a Node compatibility host and explicit concurrency tools. The useful comparison is which compiler and host combination can run your program and preserve the behavior it relies on.</p>''' + hermes_table + '''<p class="small-note">Static Hermes architecture entries come from its <a href="https://github.com/facebook/hermes/blob/static_h/doc/blog/2024-12-23-compiling-javascript-to-wasm.md">published compilation article</a>. The kiln harness behavior is visible in the <a href="''' + source + '''bench/realworld/compare.py">pinned runner source</a>.</p><h2>TypeScript diagnostics are their own compatibility target.</h2><p>Accepting annotations, making sound type guarantees and matching TypeScript diagnostics are separate goals. Static Hermes’s optional typing design should be evaluated on its own terms. For a TypeScript project, decide how authored source is checked and lowered before comparing the compiled program.</p><p>kiln includes <code>kiln check</code>, with TypeScript 7.0.2 library inputs and recorded exact and partial diagnostic matches. Compiler contracts can help guarded native specialization; unchecked annotations are not runtime proofs. <a href="../reference/type-checking.html">TypeScript checker architecture and recorded differences</a>.</p><h2>Language semantics and host APIs both matter.</h2><p>A standalone JavaScript engine and a Node application runtime solve different integration problems. For a file-processing CLI or HTTP service, check filesystem, networking, module resolution and lifecycle behavior in the actual host you plan to ship.</p><p>kiln supplies a Node adapter and native builds for those programs. Its conformance reference separates ECMAScript behavior, diagnostic fidelity and real package smoke tests. Typed actors, parallel collections and immutable graph sharing are additional application APIs. <a href="../reference/conformance.html">Conformance evidence</a> · <a href="../reference/builtins.html">Built-in API reference</a>.</p><h2>Do not confuse Hermes bytecode with native AOT.</h2><p>kiln’s existing real-world runner invokes <code>hermesc -emit-binary</code> to produce an HBC file and executes that file with <code>hvm</code>. Building those tools from <code>static_h</code> does not turn that execution into a native-AOT benchmark. That lane can inform bytecode comparisons, but it cannot establish a kiln-versus-Static-Hermes native speed ranking. <a href="''' + source + '''bench/realworld/compare.py">Inspect the exact build and execution commands</a>.</p><h2>Which should you evaluate first?</h2><p>Evaluate Static Hermes when your work centers on JavaScript engine integration, its typing approach or native/Wasm compiler research. Evaluate kiln when you want a TypeScript CLI or service workflow with package resolution, source diagnostics and built-in ownership APIs. Run the same program in the intended host before deciding.</p><p><a href="../#start">Try kiln</a> · <a href="https://github.com/facebook/hermes/tree/static_h">Explore Static Hermes</a>. There is no matched native-AOT performance result for this pairing on this site.</p></section>'''
document('kiln-vs-static-hermes.html','kiln vs Static Hermes: Native JavaScript Compared','Compare kiln and Static Hermes for native compilation, TypeScript diagnostics and application host APIs, including the distinction between Hermes bytecode and native AOT.',hermes)

porffor_table = table('Porffor (documented)', [
    ('Native output', 'Generated C compiled with a system C compiler.', 'Ahead-of-time native executables; compiles needed runtime built-ins into the artifact.'),
    ('TypeScript workflow', 'Embedded source checker, interpreter and native build commands.', 'Parses TypeScript syntax directly; native executable workflow.'),
    ('Modules and packages', 'Node-style ESM/CommonJS resolution; declare runtime-selected modules for native inclusion.', 'Plain builds use a single bundled file; server mode bundles imports with esbuild.'),
    ('HTTP APIs', 'Node HTTP adapter and Request/Response handlers through Kiln.serve.', 'Fetch-style server handlers backed by uWebSockets; documented surface limits.'),
])
porffor = '''<section><h2>Both compile ahead of time. Compare the application boundary.</h2><p>Porffor compiles JavaScript and TypeScript to native executables with the needed language runtime built into the artifact. Its docs position compatibility as something to test while the project is pre-alpha. <a href="https://porffor.dev/docs/">Porffor’s native compilation workflow</a>.</p><p>kiln combines an interpreter for immediate runs with native builds, TypeScript source diagnostics and a Node-oriented application host. The decision depends on how your code uses modules, dependencies, I/O and concurrency, as well as the language features it exercises.</p>''' + porffor_table + '''<p class="small-note">Porffor entries summarize its <a href="https://porffor.dev/docs/">overview</a>, <a href="https://porffor.dev/docs/adapt.html">project adaptation guide</a> and <a href="https://porffor.dev/docs/http.html">HTTP server contract</a>.</p><h2>Existing npm projects need more than syntax support.</h2><p>Porffor’s plain builds accept a single source file; its adaptation guide recommends bundling and auditing Node-specific assumptions. Server builds perform bundling automatically. <a href="https://porffor.dev/docs/adapt.html">Porffor’s module and runtime boundary</a>.</p><p>kiln resolves ESM and CommonJS packages through its Node layer. Its committed 2026-10-11 record contains 361/361 passing pinned package smoke tests in native-dev mode, with native stdout compared byte for byte against Node. That is inspectable evidence for the exercised APIs, not blanket npm compatibility. Runtime-selected module paths still need explicit native inclusion. <a href="../reference/npm-compatibility.html">All package results and native inclusion rules</a>.</p><h2>Both have a native HTTP path.</h2><p>Porffor now documents fetch-style servers using uWebSockets. Its contract lists limits including loopback binding, one-piece text responses and absent outbound fetch. <a href="https://porffor.dev/docs/http.html">Porffor’s current HTTP surface</a>.</p><p>kiln offers core Node HTTP APIs and a Request/Response interface through <code>Kiln.serve</code>. Its website publishes workload-specific HTTP measurements against Node, Bun and Deno; these do not measure Porffor. Choose representative routing, request-body and asynchronous workloads rather than extrapolating from hello world. <a href="../#measured">Measured workloads and conditions</a> · <a href="../reference/builtins.html#extensions">Server example</a>.</p><h2>Read old npm comparisons as historical evidence.</h2><p>The repository retains a September 30, 2026 comparison derived from Porffor’s then-public dashboard and kiln-authored tests. They were different smoke programs, and the record predates kiln runner corrections. It is not a contemporary shared-test ranking. This page therefore does not place kiln’s newer 361/361 result beside that older Porffor percentage. <a href="''' + source + '''conformance/npm-compat/README.md">Original methodology and historical caveats</a>.</p><h2>Which should you evaluate first?</h2><p>Evaluate Porffor for a bounded compiled core or a service that fits its documented server contract. Evaluate kiln when source TypeScript checking, Node-oriented dependencies, typed actors or shared immutable data are central to the application. Both benefit from testing the actual program’s output and lifecycle before measuring speed.</p><pre><code>kiln check app.ts\nkiln run app.ts\nkiln build app.ts\n./app</code></pre><p><a href="../#start">Install kiln</a> · <a href="https://porffor.dev/docs/">Try Porffor’s workflow</a>. No matched current kiln-versus-Porffor performance result is published here.</p></section>'''
document('kiln-vs-porffor.html','kiln vs Porffor: Native TypeScript and npm Compared','Compare kiln and Porffor for native TypeScript compilation, npm package workflows, HTTP servers and compatibility evidence, with current upstream documentation.',porffor)
print('Rendered comparison hub and three sourced comparison pages.')
